/**
 * Unit tests for JacksonAnnotationIntrospector.findRootName
 */
public class JacksonAnnotationIntrospector_findRootName_TriageGen1Test {

    private JacksonAnnotationIntrospector introspector;
    private AnnotatedClass annotatedClass;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        annotatedClass = Mockito.mock(AnnotatedClass.class);
    }

    /**
     * Tests the case where the @JsonRootName annotation is not present.
     * Covers: if (ann == null) { return null; }
     */
    @Test
    public void testFindRootName_NoAnnotation() {
        // Mock _findAnnotation to return null
        // Since _findAnnotation is protected, we rely on the fact that 
        // the introspector uses it to look up the annotation on the annotatedClass.
        // We need to mock the behavior that results in _findAnnotation returning null.
        // In a real Jackson environment, _findAnnotation calls annotatedClass.getAnnotation().

        // We simulate the internal logic behavior by mocking the annotatedClass interaction 
        // if possible, or by using a spy if _findAnnotation was public. 
        // However, since we are testing the logic of findRootName:

        // We create a subclass to override the protected method for testing purposes 
        // to control the return value of _findAnnotation.
        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected <T extends Annotation> T _findAnnotation(AnnotatedClass ac, Class<T> annotationType) {
                return null;
            }
        };

        PropertyName result = spyIntrospector.findRootName(annotatedClass);
        assertNull("Should return null when annotation is missing", result);
    }

    /**
     * Tests the case where @JsonRootName is present with a value and a valid namespace.
     * Covers: normal path and PropertyName.construct(ann.value(), ns)
     */
    @Test
    public void testFindRootName_WithValueAndNamespace() {
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn("http://example.com");

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected <T extends Annotation> T _findAnnotation(AnnotatedClass ac, Class<T> annotationType) {
                return (T) mockAnn;
            }
        };

        PropertyName result = spyIntrospector.findRootName(annotatedClass);

        assertEquals("root", result.getLogicalName());
        assertEquals("http://example.com", result.getNamespace());
    }

    /**
     * Tests the case where @JsonRootName is present with a value and an empty namespace string.
     * Covers: if (ns != null && ns.length() == 0) { ns = null; }
     */
    @Test
    public void testFindRootName_WithEmptyNamespace() {
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn(""); // Empty string

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected <T extends Annotation> T _findAnnotation(AnnotatedClass ac, Class<T> annotationType) {
                return (T) mockAnn;
            }
        };

        PropertyName result = spyIntrospector.findRootName(annotatedClass);

        assertEquals("root", result.getLogicalName());
        assertNull("Empty namespace should be converted to null", result.getNamespace());
    }

    /**
     * Tests the case where @JsonRootName is present with a value and a null namespace.
     * Covers: ns != null check
     */
    @Test
    public void testFindRootName_WithNullNamespace() {
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn(null);

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected <T extends Annotation> T _findAnnotation(AnnotatedClass ac, Class<T> annotationType) {
                return (T) mockAnn;
            }
        };

        PropertyName result = spyIntrospector.findRootName(annotatedClass);

        assertEquals("root", result.getLogicalName());
        assertNull("Namespace should remain null", result.getNamespace());
    }
}
